diff --git a/mail/base/content/aboutMessage.js b/mail/base/content/aboutMessage.js
index c0af83e75e3..04131a84139 100644
--- a/mail/base/content/aboutMessage.js
+++ b/mail/base/content/aboutMessage.js
@@ -309,6 +309,9 @@ function displayMessage(uri, viewWrapper) {
     invalidate() {},
     invalidateRange() {},
     rowCountChanged(idx, count) {
+      if (!gDBView.selection) {
+        return;
+      }
       const wasSuppressed = gDBView.selection.selectEventsSuppressed;
       gDBView.selection.selectEventsSuppressed = true;
       gDBView.selection.adjustSelection(idx, count);
diff --git a/mail/base/content/mailCommon.js b/mail/base/content/mailCommon.js
index 866cbfa99cb..123b926bcaa 100644
--- a/mail/base/content/mailCommon.js
+++ b/mail/base/content/mailCommon.js
@@ -1154,13 +1154,13 @@ var dbViewWrapperListener = {
       if (location.href == "about:3pane") {
         // In a 3-pane tab, clear the message pane and selection.
         window.threadTree.selectedIndex = -1;
-      } else if (parent?.location != "about:3pane") {
+      } else if (window.parent && window.parent.location != "about:3pane") {
         // In a standalone message tab or window, close the tab or window.
-        const tabmail = top.document.getElementById("tabmail");
+        const tabmail = window.parent.document.getElementById("tabmail");
         if (tabmail) {
           tabmail.closeTab(window.tabOrWindow);
         } else {
-          top.close();
+          window.parent.close();
         }
       }
       this._nextViewIndexAfterDelete = null;
